@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&family=Noto+Sans+SC:wght@300;400;700&display=swap');

:root {
  --primary-color: #00d8ff;
  --secondary-color: #7b68ee;
  --accent-color: #ff6b9d;
  --bg-color: #0a0a0a;
  --text-color: #e0e0e0;
  --heading-color: #ffffff;
}

body {
  font-family: 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
  background: linear-gradient(135deg, #0a0a0a 0%, #1a1a2e 100%);
  color: var(--text-color);
  min-height: 100vh;
}

header {
  background: rgba(10, 10, 10, 0.9) !important;
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(0, 216, 255, 0.3);
}

header .logo {
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  font-size: 1.5em;
  background: linear-gradient(90deg, var(--primary-color), var(--secondary-color));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

#nav-menu a {
  color: var(--text-color) !important;
  transition: all 0.3s ease;
}

#nav-menu a:hover {
  color: var(--primary-color) !important;
  text-shadow: 0 0 10px var(--primary-color);
}

#main-title {
  font-family: 'JetBrains Mono', monospace;
  font-size: 2.5em;
  background: linear-gradient(90deg, var(--primary-color), var(--accent-color));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

#sidebar {
  background: rgba(26, 26, 46, 0.5);
  border-radius: 15px;
  padding: 20px;
}

.widget {
  background: rgba(255, 255, 255, 0.05);
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.post {
  background: rgba(26, 26, 46, 0.6);
  border-radius: 15px;
  padding: 25px;
  margin-bottom: 30px;
  border: 1px solid rgba(0, 216, 255, 0.2);
  transition: all 0.3s ease;
}

.post:hover {
  border-color: var(--primary-color);
  box-shadow: 0 0 20px rgba(0, 216, 255, 0.2);
  transform: translateY(-2px);
}

.post-title {
  font-family: 'JetBrains Mono', monospace;
  font-size: 1.8em;
  color: var(--heading-color);
}

.post-title a {
  color: var(--heading-color) !important;
  transition: color 0.3s ease;
}

.post-title a:hover {
  color: var(--primary-color) !important;
}

.post-meta {
  color: rgba(255, 255, 255, 0.6);
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.85em;
}

.post-content {
  line-height: 1.8;
}

.post-content h1, .post-content h2, .post-content h3 {
  color: var(--heading-color);
  font-family: 'JetBrains Mono', monospace;
  border-left: 3px solid var(--primary-color);
  padding-left: 15px;
  margin: 1.5em 0;
}

.post-content code {
  background: rgba(0, 216, 255, 0.15);
  color: var(--primary-color);
  padding: 2px 8px;
  border-radius: 4px;
  font-family: 'JetBrains Mono', monospace;
}

.post-content pre {
  background: #1e1e1e;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.post-content pre code {
  background: none;
  color: #a9b7c6;
}

blockquote {
  background: linear-gradient(90deg, rgba(0, 216, 255, 0.1), rgba(123, 104, 238, 0.1));
  border-left: 4px solid var(--secondary-color);
  padding: 15px 20px;
  margin: 1em 0;
  border-radius: 0 10px 10px 0;
}

blockquote p {
  margin: 0;
  color: var(--text-color);
  font-style: italic;
}

footer {
  background: rgba(10, 10, 10, 0.95) !important;
  border-top: 1px solid rgba(0, 216, 255, 0.3);
  padding: 20px;
  text-align: center;
}

footer a {
  color: var(--primary-color) !important;
}

::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #0a0a0a;
}

::-webkit-scrollbar-thumb {
  background: var(--primary-color);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--secondary-color);
}

@media (max-width: 768px) {
  #main-title {
    font-size: 1.8em;
  }

  .post {
    padding: 15px;
  }

  .post-title {
    font-size: 1.4em;
  }
}

